"use client";

import { userApi } from "@/services/api";
import { Button, EmptyState, ErrorState, formatDate, Icon, PageHeader, Panel, Skeleton, StatePill, toast, useAccessToken, useVendorQuery } from "@/components/portal";
type Notice={id:string;type:string;title:string;message:string;read_at:string|null;created_at:string;booking_id:string|null};type Page={items:Notice[];total:number;unread:number};
export default function VendorNotificationsPage(){const token=useAccessToken();const q=useVendorQuery<Page>("/notifications?limit=100",token);async function mark(id?:string){if(!token)return;try{if(id)await userApi(`/notifications/${id}/read`,token,{method:"PATCH"});else await userApi("/notifications/read-all",token,{method:"POST"});q.reload();toast("Notification state saved");}catch(error){toast(error instanceof Error?error.message:"Could not update notifications");}}
  return <><PageHeader eyebrow="ACCOUNT ACTIVITY" title="Notifications" description="Booking, restaurant order, hotel reservation, and support updates addressed to your signed-in account." action={<Button variant="secondary" disabled={!q.data?.unread} onClick={()=>void mark()}><Icon name="check"/>Mark all read</Button>}/><Panel className="panel-pad">{q.loading?<Skeleton rows={6}/>:q.error?<ErrorState message={q.error} onRetry={q.reload}/>:!q.data?.items.length?<EmptyState title="No notifications yet" description="Persisted account updates will appear here when business events occur."/>:<div className="data-table-wrap"><table className="data-table"><thead><tr><th>Notification</th><th>Type</th><th>Created</th><th>Status</th><th/></tr></thead><tbody>{q.data.items.map((item)=><tr key={item.id}><td><strong>{item.title}</strong><small style={{display:"block",whiteSpace:"normal"}}>{item.message}</small></td><td>{item.type.replaceAll("_"," ")}</td><td>{formatDate(item.created_at,{dateStyle:"medium",timeStyle:"short"})}</td><td><StatePill value={item.read_at?"read":"unread"}/></td><td>{item.read_at?null:<button className="action-link" onClick={()=>void mark(item.id)}>Mark read</button>}</td></tr>)}</tbody></table></div>}</Panel></>;
}
